    "imageUrl": "https://imagens.ebc.com.br/sKPd4d8UKTn0AdJBba5m8qn_d50=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/10/25/0d4a6236.jpg?itok=3AF9OK3O",
